sy(){ gr "$C"&&ao "$C" "$CT"&&cn "$C"&&[ "$(bn "$C")" = main ]&&fp "$C"||return 1;an "$C" "$(hh "$C")" "$(om "$C")"&&git -C "$C" merge --ff-only origin/main >/dev/null||return 1;echo 'CONTEXT SYNCED';};dc(){ [ -d "$C" ]||{ echo 'dev-context=not-installed';return;};gr "$C"||return 1;echo "dev-context=$C branch=$(bn "$C") head=$(hh "$C") clean=$([ cn "$C" ]&&echo yes||echo no)";cn "$C";};
